import{_ as a,o as n,c as e,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const c=JSON.parse('{"title":"1. 计算机发展史纵贯线: 1936 → 2026","description":"","frontmatter":{},"headers":[],"relativePath":"prologue/history.md","filePath":"prologue/history.md","lastUpdated":1788475713000}'),o={name:"prologue/history.md"};function i(l,t,r,u,p,d){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="_1-计算机发展史纵贯线-1936-→-2026" tabindex="-1">1. 计算机发展史纵贯线: 1936 → 2026 <a class="header-anchor" href="#_1-计算机发展史纵贯线-1936-→-2026" aria-label="Permalink to &quot;1. 计算机发展史纵贯线: 1936 → 2026&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>90 年计算机史用三条线索串起</strong>: (1) <strong>形式系统</strong>: &quot;什么是可计算&quot;逐步被严格定义;(2) <strong>硬件能力</strong>: 计算速度、内存、IO 用摩尔定律等指数曲线提升, 价位指数下降, 推动&quot;软件范式&quot;被迫重组; (3) <strong>抽象层级</strong>: 每一代工程师不得不引入新抽象来对抗复杂度, 把上一代底层细节封装到契约里.</p><p>每一节都讲: <strong>那年发生了什么 / 缔造了什么契约 / 把什么写进了&quot;已经不可能回退&quot;的清单</strong>.</p><p>读完应能: 用 20 分钟讲清计算机从 Turing → 2026 推理模型时代的关键节点, 每个节点一句话点破质变.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>2025-2026 段落已按 2026-08 公开资料（原厂 release note / 主流媒体）核对；模型发布与数字以官方口径为准。</p></div><hr><h2 id="_0-概览图" tabindex="-1">0. 概览图 <a class="header-anchor" href="#_0-概览图" aria-label="Permalink to &quot;0. 概览图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1936   Turing 论文 &quot;On Computable Numbers...&quot;</span></span>
<span class="line"><span>1945   von Neumann 架构报告; ENIAC 完成</span></span>
<span class="line"><span>1947   Bell Labs 三人组发明晶体管</span></span>
<span class="line"><span>1957   Sputnik → ARPA 成立; FORTRAN; IBM 360 开端</span></span>
<span class="line"><span>1961   COBOL; 第一台分时系统 CTSS</span></span>
<span class="line"><span>1969   UNIX Prototype (Bell Labs); ARPANET 起</span></span>
<span class="line"><span>1971   Intel 4004; 第一台微处理器; 软盘</span></span>
<span class="line"><span>1975   Altair 8800 → Bill Gates/Microsoft; &quot;个人计算&quot; 概念</span></span>
<span class="line"><span>1977   Apple II; Commodore PET; TRS-80</span></span>
<span class="line"><span>1981   IBM PC (开放架构 → clone 洪流 → Wintel 垄断)</span></span>
<span class="line"><span>1985   Windows 1.0; ARM1 (Acorn)</span></span>
<span class="line"><span>1991   Linux 0.01 (Linus); WWW 第一网页</span></span>
<span class="line"><span>1993   Mosaic → Web 爆炸; iPhone 之父在此出生</span></span>
<span class="line"><span>1995   Win95; Java 1.0; Amazon/eBay (Web 商业化)</span></span>
<span class="line"><span>2006   AWS EC2 起; iPhone (2007); 触屏 + app store</span></span>
<span class="line"><span>2012   AlexNet (ImageNet top-5 &lt; 16%, GPU 训练); &quot;深度学习 = GPU&quot;</span></span>
<span class="line"><span>2017   Transformer / &quot;Attention Is All You Need&quot;</span></span>
<span class="line"><span>2020   COVID → 数亿人远程办公 → 云速率 5x; 扩散模型</span></span>
<span class="line"><span>2022   ChatGPT —— 5 天注册破 100M; RLHF 出现工程化</span></span>
<span class="line"><span>2023   LLaMA / Qwen / DeepSeek 系; 开源 70B 可单机推理</span></span>
<span class="line"><span>2024   NPU / H100 / TPU v5p / Groq / Cerebras / 量子计算长征</span></span>
<span class="line"><span>       Blackwell B200 / GB200 NVL72 (NVIDIA); DeepSeek-V3 开源 (12 月)</span></span>
<span class="line"><span>2025   GPT-5 统一 o 系; Claude 4.x / Gemini 3 / Grok 4 推理模型常态化;</span></span>
<span class="line"><span>       DeepSeek-R1 &quot;时刻&quot;; Agentic AI + MCP; gpt-oss 开源; HBM4 量产;</span></span>
<span class="line"><span>       Google Willow 低于阈值量子纠错</span></span>
<span class="line"><span>2026   GPT-5.x→5.6 / Claude 5 / Gemini 3.6 Flash / DeepSeek R2 快节奏迭代;</span></span>
<span class="line"><span>       NVIDIA Rubin 量产 + AMD MI450; 昇腾 950 超节点 (1024 卡);</span></span>
<span class="line"><span>       HBM4 三家量产 (~2 TB/s/stack) + CXL 3.2; 量子数十逻辑 qubit</span></span></code></pre></div><hr><h2 id="一、1936-1945-可计算性的形式化-第一台通用电子计算机" tabindex="-1">一、1936-1945: 可计算性的形式化 + 第一台通用电子计算机 <a class="header-anchor" href="#一、1936-1945-可计算性的形式化-第一台通用电子计算机" aria-label="Permalink to &quot;一、1936-1945: 可计算性的形式化 + 第一台通用电子计算机&quot;">​</a></h2><h3 id="_1-1-church-turing-论题-1936" tabindex="-1">1.1 Church-Turing 论题 (1936) <a class="header-anchor" href="#_1-1-church-turing-论题-1936" aria-label="Permalink to &quot;1.1 Church-Turing 论题 (1936)&quot;">​</a></h3><ul><li><strong>Alan Turing</strong>: 论文 <em>On Computable Numbers, with an Application to the Entscheidungsproblem</em> 提出 Turing Machine.</li><li><strong>Alonzo Church</strong>: lambda calculus 同期给出等价定义.</li><li><strong>Church-Turing 论题</strong>: 任何&quot;算法可计算&quot;的函数 = TM 可计算 (直觉但<strong>不是定理</strong>, 是把&quot;算法定义&quot;和&quot;TM 定义&quot;绑成一体).</li></ul><p>→ 回到 <a href="./../theory/turing-machine">第九部分 计算理论</a> 看形式化定义与停机问题.</p><h3 id="_1-2-第二次世界大战的硬件倒逼" tabindex="-1">1.2 第二次世界大战的硬件倒逼 <a class="header-anchor" href="#_1-2-第二次世界大战的硬件倒逼" aria-label="Permalink to &quot;1.2 第二次世界大战的硬件倒逼&quot;">​</a></h3><ul><li><strong>Colossus</strong> (1943, Bletchley Park) 破译 Lorenz 密码的专用机器 (非通用).</li><li><strong>ENIAC</strong> (1945, Eckert &amp; Mauchly, 宾大): 第一台通用电子数字计算机. 17468 真空管、30 吨、5 kW、每秒 5000 加法.</li><li><strong>EDVAC 报告</strong> (1945, von Neumann): 提出<strong>存储程序</strong>架构, CPU + 内存 + IO 三分, 指令和数据同存内存. 这就是后世&quot;von Neumann 架构&quot;.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>这个架构的&quot;存储程序 + 共享总线&quot;是把<strong>冯诺依曼瓶颈</strong>钉死在所有现代 CPU 里. CPU 与内存的频率差距至今不断拉开, 这就是为什么 HBM / CXL / NUMA 等手段反复被发明 — 都是绕过 1945 那条契约.</p></div><hr><h2 id="二、1947-1960-晶体管-大型机-高级语言" tabindex="-1">二、1947-1960: 晶体管 + 大型机 + 高级语言 <a class="header-anchor" href="#二、1947-1960-晶体管-大型机-高级语言" aria-label="Permalink to &quot;二、1947-1960: 晶体管 + 大型机 + 高级语言&quot;">​</a></h2><h3 id="_2-1-晶体管-1947" tabindex="-1">2.1 晶体管 (1947) <a class="header-anchor" href="#_2-1-晶体管-1947" aria-label="Permalink to &quot;2.1 晶体管 (1947)&quot;">​</a></h3><p>Bell Labs 的 Shockley / Bardeen / Brattain 发明点接触晶体管 (Nobel 1956). 替代真空管: 体积小、能耗低、长寿命 → 可堆大规模. 没它就没有集成电路.</p><h3 id="_2-2-集成电路-1958" tabindex="-1">2.2 集成电路 (1958) <a class="header-anchor" href="#_2-2-集成电路-1958" aria-label="Permalink to &quot;2.2 集成电路 (1958)&quot;">​</a></h3><ul><li>Jack Kilby (TI) 与 Robert Noyce (Fairchild) 几乎同时分别发明 IC.</li><li>1965 Gordon Moore 提出 Moore 定律 (每 18-24 月晶体管数翻倍). 半个世纪后这条曲线仍未平.</li></ul><h3 id="_2-3-大型机时代-1955-1975" tabindex="-1">2.3 大型机时代 (1955-1975) <a class="header-anchor" href="#_2-3-大型机时代-1955-1975" aria-label="Permalink to &quot;2.3 大型机时代 (1955-1975)&quot;">​</a></h3><ul><li><strong>IBM 701</strong> (1952): IBM 第一台商用电子计算机.</li><li><strong>IBM S/360</strong> (1964): 主打&quot;全系列兼容&quot;, 引入 ISA (instruction set architecture) 与 microarch 分离的概念. 这一台机器让&quot;程序员一旦写汇编, 在更高型号同运行&quot;成为可能, 也让<strong>ISA 抽象</strong>成为行业必需.</li></ul><p>→ 这是&quot;计算机抽象层级&quot;的真正起点, 见 <a href="./abstraction-layers">abstraction-layers</a>.</p><h3 id="_2-4-高级语言史-1957-1972" tabindex="-1">2.4 高级语言史 (1957-1972) <a class="header-anchor" href="#_2-4-高级语言史-1957-1972" aria-label="Permalink to &quot;2.4 高级语言史 (1957-1972)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>语言</th><th>出发点</th></tr></thead><tbody><tr><td>1957</td><td>FORTRAN (IBM)</td><td>科学计算; 之前手写汇编</td></tr><tr><td>1959</td><td>COBOL</td><td>商业数据处理 (DoD 推)</td></tr><tr><td>1958</td><td>LISP</td><td>符号计算, AI 起源</td></tr><tr><td>1964</td><td>BASIC</td><td>教学, 简化学生入门</td></tr><tr><td>1970</td><td>Pascal</td><td>结构化编程教学</td></tr><tr><td>1972</td><td>C (Ritchie)</td><td>用来重写 Unix, &quot;可移植汇编&quot;</td></tr></tbody></table><p>→ <strong>C 与 Unix 是孪生兄弟</strong>; 操作系统首次可移植 (PDP-7 → PDP-11 → VAX). 这件事让&quot;硬件厂家锁定&quot;被反复松动, 是后续一切的种子.</p><hr><h2 id="三、1969-1981-unix-arpanet-微处理器-pc" tabindex="-1">三、1969-1981: Unix + ARPANET + 微处理器 + PC <a class="header-anchor" href="#三、1969-1981-unix-arpanet-微处理器-pc" aria-label="Permalink to &quot;三、1969-1981: Unix + ARPANET + 微处理器 + PC&quot;">​</a></h2><h3 id="_3-1-unix-1969" tabindex="-1">3.1 Unix (1969) <a class="header-anchor" href="#_3-1-unix-1969" aria-label="Permalink to &quot;3.1 Unix (1969)&quot;">​</a></h3><p>Ken Thompson &amp; Dennis Ritchie 在 Bell Labs 为 PDP-7 写&quot;unics&quot; (-&gt; Unix), 后用 C 重写为可移植 OS. 几乎所有现代 OS (Linux, macOS, iOS, Android 底层, BSD) 都直接或间接是 Unix 派生.</p><p><strong>贡献</strong>: 文件即字节流 / 进程 / fork-exec / pipe / 小工具组合的 shell 哲学 / 网络套接字.</p><p>→ 本书 <a href="./../os/">第二部分 OS</a> 几乎是 Unix 与 Linux 工程化的延伸.</p><h3 id="_3-2-arpanet-1969" tabindex="-1">3.2 ARPANET (1969) <a class="header-anchor" href="#_3-2-arpanet-1969" aria-label="Permalink to &quot;3.2 ARPANET (1969)&quot;">​</a></h3><p>第一个分组交换网络; 4 节点起步 (UCLA / SRI / UCSB / Utah). 1973 TCP/IP 雏形 (Cerf-Kahn). 1983 NSFNET 升级 TCP/IP, &quot;互联网&quot; 实质开始.</p><p>1971 Ray Tomlinson 发第一封 email. 1976 Apple I 卖给爱好者; 1977 Apple II 内置 BASIC + 成品机箱; 1981 IBM PC 出货, 标致&quot;个人计算机&quot;被企业级认可.</p><h3 id="_3-3-intel-4004-1971-第一颗微处理器" tabindex="-1">3.3 Intel 4004 (1971): 第一颗微处理器 <a class="header-anchor" href="#_3-3-intel-4004-1971-第一颗微处理器" aria-label="Permalink to &quot;3.3 Intel 4004 (1971): 第一颗微处理器&quot;">​</a></h3><p>Intel 4004 = 2300 晶体管, 4-bit, 740 kHz. 上面运行 Busicom 打印机的计算. 这件事的本质: <strong>CPU 也能做成芯片</strong>而不再是机房箱柜. 后续 8080/8086 (1978 x86 起) 一步步推.</p><h3 id="_3-4-altair-8800-1975-与-microsoft-起步" tabindex="-1">3.4 Altair 8800 (1975) 与 Microsoft 起步 <a class="header-anchor" href="#_3-4-altair-8800-1975-与-microsoft-起步" aria-label="Permalink to &quot;3.4 Altair 8800 (1975) 与 Microsoft 起步&quot;">​</a></h3><p>Pop Electronics 1975 封面 Altair 8800 → 哈佛大二学生 Bill Gates 与 Paul Allen 写 Altair BASIC 解释器, 一年不到成立 Microsoft. &quot;软件&quot;作为商品第一次清晰化.</p><hr><h2 id="四、1981-1995-pc-标准化-gui-互联网基础" tabindex="-1">四、1981-1995: PC 标准化 + GUI + 互联网基础 <a class="header-anchor" href="#四、1981-1995-pc-标准化-gui-互联网基础" aria-label="Permalink to &quot;四、1981-1995: PC 标准化 + GUI + 互联网基础&quot;">​</a></h2><h3 id="_4-1-ibm-pc-1981" tabindex="-1">4.1 IBM PC (1981) <a class="header-anchor" href="#_4-1-ibm-pc-1981" aria-label="Permalink to &quot;4.1 IBM PC (1981)&quot;">​</a></h3><ul><li>用 Intel 8088 (4.77 MHz, 16-bit 内核 + 8-bit 外总线); OS 用 Microsoft DOS (买断 Seattle Computer 产品 QDOS 改名).</li><li><strong>关键</strong>: 架构未保密 → Compaq / Phoenix BIOS 等厂商大量克隆 → &quot;PC 兼容机&quot;潮 → x86 成为事实标准.</li></ul><p>→ <strong>x86 vs ARM</strong> 分叉的故事从这年开始, 见 <a href="./mainframe-xpu">mainframe-xpu</a>.</p><h3 id="_4-2-wimp-gui" tabindex="-1">4.2 WIMP + GUI <a class="header-anchor" href="#_4-2-wimp-gui" aria-label="Permalink to &quot;4.2 WIMP + GUI&quot;">​</a></h3><ul><li>1973 Xerox PARC 的 Alto 第一次实现 GUI (windows, icons, mouse, popup).</li><li>1984 Apple Macintosh 商业化 GUI. 1985 Windows 1.0.</li><li>1989 Tim Berners-Lee 在 CERN 提 HyperText + HTTP/HTML, 写下第一个 web server.</li></ul><h3 id="_4-3-lan-与数据库" tabindex="-1">4.3 LAN 与数据库 <a class="header-anchor" href="#_4-3-lan-与数据库" aria-label="Permalink to &quot;4.3 LAN 与数据库&quot;">​</a></h3><ul><li>1980 Novell NetWare / 3Com Ethernet 网卡让办公室组 LAN 成常态.</li><li><strong>关系数据库</strong> 1970 Codd 论文 → Oracle (1979) / IBM DB2 (1983) / PostgreSQL前身 Postgres (1996). 这是 <a href="./../databases/">第四部分数据库</a> 的源头.</li></ul><hr><h2 id="五、1991-2001-linux-web-开源" tabindex="-1">五、1991-2001: Linux + Web + 开源 <a class="header-anchor" href="#五、1991-2001-linux-web-开源" aria-label="Permalink to &quot;五、1991-2001: Linux + Web + 开源&quot;">​</a></h2><h3 id="_5-1-linux-1991" tabindex="-1">5.1 Linux (1991) <a class="header-anchor" href="#_5-1-linux-1991" aria-label="Permalink to &quot;5.1 Linux (1991)&quot;">​</a></h3><p>Linus Torvalds 在赫尔辛基大学宿舍写 Linux 0.01 (1991-08-25 公告), 1992 GPL 化 → 开源爆发. 90 年代 ~ 一切服务器都 Linux 化; &quot;LAMP stack&quot; (Linux+Apache+MySQL+PHP) 成为 web 默认.</p><p>→ 这是 Unix 之外<strong>第二支不锁厂商的开源 OS</strong>, 给后续 web 服务、云计算、AI 训练堆栈全部用 Linux 作底.</p><h3 id="_5-2-world-wide-web-1991" tabindex="-1">5.2 World Wide Web (1991) <a class="header-anchor" href="#_5-2-world-wide-web-1991" aria-label="Permalink to &quot;5.2 World Wide Web (1991)&quot;">​</a></h3><p>Tim Berners-Lee 在 CERN 部署第一个 web server, HTTP 0.9 / HTML. 1993 Marc Andreessen 写 Mosaic 浏览器 → Netscape (1994) → 商业化 web.</p><p>→ 后续影响 <a href="./../networking/">第三部分网络</a> 的一切. HTTP 是几乎所有协议层的&quot;最后一公里&quot;.</p><h3 id="_5-3-开源浪潮" tabindex="-1">5.3 开源浪潮 <a class="header-anchor" href="#_5-3-开源浪潮" aria-label="Permalink to &quot;5.3 开源浪潮&quot;">​</a></h3><ul><li>1985 GNU (Richard Stallman) → GCC, glibc, bash, Emacs.</li><li>1991 Linux + 1995 Apache HTTP 服务器 + 1996 PostgreSQL + 2005 Git.</li></ul><p>→ 2000 年后开源几乎成为基础设施软件默认形态, 也是 AI 时代模型托管 (HuggingFace) 的预设.</p><hr><h2 id="六、2001-2010-web-2-0-移动-arm-逆袭-虚拟化" tabindex="-1">六、2001-2010: Web 2.0 + 移动 + ARM 逆袭 + 虚拟化 <a class="header-anchor" href="#六、2001-2010-web-2-0-移动-arm-逆袭-虚拟化" aria-label="Permalink to &quot;六、2001-2010: Web 2.0 + 移动 + ARM 逆袭 + 虚拟化&quot;">​</a></h2><h3 id="_6-1-ajax-web-2-0-2004-2005" tabindex="-1">6.1 AJAX + Web 2.0 (2004-2005) <a class="header-anchor" href="#_6-1-ajax-web-2-0-2004-2005" aria-label="Permalink to &quot;6.1 AJAX + Web 2.0 (2004-2005)&quot;">​</a></h3><ul><li>Gmail (2004) / Google Maps (2005) 引爆 AJAX → 浏览器成&quot;富客户端&quot;, SPA (Single Page App) 兴起.</li><li>2006 AWS EC2 商业化 (虚拟机租用), 启云时代.</li></ul><h3 id="_6-2-iphone-触屏-app-store-2007" tabindex="-1">6.2 iPhone + 触屏 + App Store (2007) <a class="header-anchor" href="#_6-2-iphone-触屏-app-store-2007" aria-label="Permalink to &quot;6.2 iPhone + 触屏 + App Store (2007)&quot;">​</a></h3><ul><li>2007 初代 iPhone (ARM11 412 MHz, 128MB RAM) 改变&quot;手机&quot;定义: 全屏触屏 + 应用商店.</li><li>2008 Android 1.0; ARM 几乎一夜成为移动通用 CPU → 制造规模超 x86 → RISC 复兴.</li><li>2010 iPad; 2011 Chromebook.</li></ul><p>→ ARM 在手机出货量以 <strong>100×</strong> 量级碾压 x86, 后又通过 Apple Silicon M1 (2020) 与 AWS Graviton 反杀数据中心. 见 <a href="./mainframe-xpu">mainframe-xpu</a>.</p><h3 id="_6-3-虚拟化与云萌芽" tabindex="-1">6.3 虚拟化与云萌芽 <a class="header-anchor" href="#_6-3-虚拟化与云萌芽" aria-label="Permalink to &quot;6.3 虚拟化与云萌芽&quot;">​</a></h3><ul><li>1999 VMware; 2003 Xen; 2006 EC2; 2008 KVM 入 Linux 主干.</li><li>&quot;弹性的服务器&quot;成为商品 → 创业公司不需自买机架 + 上架.</li></ul><p>→ <a href="./../system-design/">第七部分系统设计</a> 的所有 case (Twitter Snowflake / Google 三件套 / Kubernetes 控制平面) 都默认这套云底座.</p><hr><h2 id="七、2010-2020-深度学习-大数据-容器化" tabindex="-1">七、2010-2020: 深度学习 + 大数据 + 容器化 <a class="header-anchor" href="#七、2010-2020-深度学习-大数据-容器化" aria-label="Permalink to &quot;七、2010-2020: 深度学习 + 大数据 + 容器化&quot;">​</a></h2><h3 id="_7-1-gpu-通用计算爆发-2007-cuda-2012-alexnet" tabindex="-1">7.1 GPU 通用计算爆发 (2007+ CUDA, 2012 AlexNet) <a class="header-anchor" href="#_7-1-gpu-通用计算爆发-2007-cuda-2012-alexnet" aria-label="Permalink to &quot;7.1 GPU 通用计算爆发 (2007+ CUDA, 2012 AlexNet)&quot;">​</a></h3><ul><li>2007 NVIDIA 推出 CUDA 让 GPU 可做通用并行.</li><li>2012 AlexNet (ImageNet top-5 error 16%) 第一次大规模用 GPU 训 CNN, <strong>一举把深度学习从学识题变成工业题</strong>.</li><li>2013-2015 VGG/ResNet/Inception; 2014 GAN; 2015 Batch Norm; 2016 ResNet (152 层可训).</li><li>2017 Transformer → 序列建模换赛道.</li></ul><h3 id="_7-2-大数据基础设施-2004-mapreduce-gfs-→-2010-spark" tabindex="-1">7.2 大数据基础设施 (2004 MapReduce / GFS → 2010 Spark) <a class="header-anchor" href="#_7-2-大数据基础设施-2004-mapreduce-gfs-→-2010-spark" aria-label="Permalink to &quot;7.2 大数据基础设施 (2004 MapReduce / GFS → 2010 Spark)&quot;">​</a></h3><ul><li>2004 Google MapReduce &amp; GFS paper → Hadoop (2006) 开源 copy.</li><li>2006 BigTable paper → Cassandra (2008) / HBase / Dynamo (2007) / Redis (2009).</li><li>2014 Kubernetes; 2015 Docker 1.0 主流; 2018 service mesh / Istio / Envoy.</li></ul><p>→ <a href="./../distributed/">第六部分分布式系统</a> 的 CAP / Paxos / Raft / K8s 全靠这十年开源沉淀.</p><h3 id="_7-3-cpu-增长遇阻-多核-加速器登场" tabindex="-1">7.3 CPU 增长遇阻 + 多核 + 加速器登场 <a class="header-anchor" href="#_7-3-cpu-增长遇阻-多核-加速器登场" aria-label="Permalink to &quot;7.3 CPU 增长遇阻 + 多核 + 加速器登场&quot;">​</a></h3><ul><li>2005 后单核性能增速放慢 (Dennard scaling 结束), 8 核 / 16 核 / 32 核 CPU 成主流.</li><li>2010 后 GPU / TPU / FPGA 在数据中心占比上升 → <strong>异构计算</strong>开篇.</li><li>2017 RISC-V 基金会成立; ISA 开源化大潮.</li></ul><p>→ 直接铺垫 <a href="./../computer-arch/">第八部分组成原理</a> 里的 GPU / TPU / NPU 章节.</p><hr><h2 id="八、2020-2024-大模型-生成式-ai-xpu-主流化" tabindex="-1">八、2020-2024: 大模型 + 生成式 AI + XPU 主流化 <a class="header-anchor" href="#八、2020-2024-大模型-生成式-ai-xpu-主流化" aria-label="Permalink to &quot;八、2020-2024: 大模型 + 生成式 AI + XPU 主流化&quot;">​</a></h2><h3 id="_8-1-关键事件" tabindex="-1">8.1 关键事件 <a class="header-anchor" href="#_8-1-关键事件" aria-label="Permalink to &quot;8.1 关键事件&quot;">​</a></h3><ul><li>2020 GPT-3 (175B); <strong>scaling law</strong> (Kaplan 2020) 起势.</li><li>2021 ViT / DALL-E; 2022 ChatGPT (5 天 +1 亿用户, 历史最快).</li><li>2022 扩散模型 (Stable Diffusion, Midjourney).</li><li>2023 LLaMA-2 (Meta); Qwen / Baichuan / DeepSeek 等中国开源; 推理成本 -90% / 半年.</li><li>2024 推理为王, TPU v5p, Groq LPU, Cerebras WSE, RISC-V 在 AI子系统, NPU 进入个人 PC 与手机, CXL 内存池化.</li></ul><h3 id="_8-2-范式迁移-cpu-时代-→-gpu-时代-→-xpu-时代" tabindex="-1">8.2 范式迁移: CPU 时代 → GPU 时代 → XPU 时代 <a class="header-anchor" href="#_8-2-范式迁移-cpu-时代-→-gpu-时代-→-xpu-时代" aria-label="Permalink to &quot;8.2 范式迁移: CPU 时代 → GPU 时代 → XPU 时代&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>算力主流芯片</th><th>开发模型</th></tr></thead><tbody><tr><td>1981-2005 CPU</td><td>x86 / ARM 单核</td><td>C / C++ / Java</td></tr><tr><td>2005-2015 多核</td><td>8-32 核 CPU</td><td>pthreads / TBB / Java util.concurrent</td></tr><tr><td>2010-2020 GPU</td><td>NVIDIA + CUDA</td><td>CUDA / OpenCL / OpenGL</td></tr><tr><td>2016-2024 加速器</td><td>TPU / NPU / DPU</td><td>高层框架 (PyTorch / JAX) + 算子级</td></tr><tr><td>2024+ XPU 异构</td><td>CPU + GPU + NPU + DPU + 量子预研</td><td>全栈编排: MLIR-on-IR + workload dispatch</td></tr></tbody></table><p>→ &quot;XPU&quot; 是 Andy Bechtolsheim 2017 命名,<strong>统一意味着异构</strong>: CPU 处理控制流, GPU 处理大并行, DPU 卸载网络与存储, NPU 在终端推理. 见 <a href="./mainframe-xpu">mainframe-xpu</a> 详述.</p><h3 id="_8-3-rlhf-工程化" tabindex="-1">8.3 RLHF 工程化 <a class="header-anchor" href="#_8-3-rlhf-工程化" aria-label="Permalink to &quot;8.3 RLHF 工程化&quot;">​</a></h3><ul><li>2022 InstructGPT → ChatGPT 把&quot;政策对齐&quot;从科研推成通用工程.</li><li>后续 DPO (Direct Preference Optimization, 2023) / RLHF with KL penalty / GRPO (DeepSeek 2024) 成主流.</li></ul><hr><h2 id="八·5、2025-2026-推理模型、agentic-ai-与-blackwell-时代" tabindex="-1">八·5、2025-2026: 推理模型、Agentic AI 与 Blackwell 时代 <a class="header-anchor" href="#八·5、2025-2026-推理模型、agentic-ai-与-blackwell-时代" aria-label="Permalink to &quot;八·5、2025-2026: 推理模型、Agentic AI 与 Blackwell 时代&quot;">​</a></h2><blockquote><p>按 2026-08 公开资料 (原厂 release note / 主流媒体) 核对; 模型发布与数字以官方口径为准.</p></blockquote><h3 id="_8-5-1-推理模型-reasoning-models-主流化" tabindex="-1">8.5.1 推理模型 (Reasoning Models) 主流化 <a class="header-anchor" href="#_8-5-1-推理模型-reasoning-models-主流化" aria-label="Permalink to &quot;8.5.1 推理模型 (Reasoning Models) 主流化&quot;">​</a></h3><ul><li><strong>OpenAI o1</strong> (2024 末) 与 <strong>o3</strong> (2025): 把 Chain-of-Thought 显式化训练, 用 RL 学习&quot;长内部思考&quot;过程; &quot;test-time compute&quot; 成为新维度.</li><li><strong>DeepSeek-R1</strong> (2025-01): 完全开源的 reasoning 模型, 凭冷启动 + 规则奖励 RL 训出一阶性能接近 o1; 价格却只有零头, 一夜踩穿美国闭源厂商定价 → &quot;<strong>DeepSeek 时刻</strong>&quot;.</li><li><strong>GPT-5 统一 o 系</strong> (2025-08): OpenAI 把 o 系并入 GPT-5 按需切换推理 / 普通模式, 同周开源 <strong>gpt-oss-120b/20b</strong> (2025-08-05, Apache 2.0); 此后按&quot;月&quot;迭代 (5.1 → 5.2 → … → 5.6), 2026-07 的 <strong>GPT-5.6</strong> 再分成 Sol / Terra / Luna 三档能力层.</li><li><strong>Anthropic</strong> (2025-2026): Claude 3.7 / 4.x 把 &quot;extended thinking&quot; 做成内置开关; 2026-02 <strong>Sonnet 4.6</strong> 首搭 1M context, 2026-06/07 进入 <strong>Claude 5 时代</strong> (Sonnet 5 / Opus 5), agentic 编程与超长上下文成为默认能力.</li><li><strong>Google / xAI</strong> (2025-11): <strong>Gemini 3 Pro</strong> 与 <strong>Grok 4.1</strong> 同期发布; 2026-07 Google 出 <strong>Gemini 3.6 Flash / 3.5 Flash-Lite / 3.5 Flash Cyber</strong> 主打 agent 效率, Grok 5 却一再跳票、只更新到 4.5 —— 大版本节奏第一次被拉开.</li><li><strong>中国开源路线齐发</strong> (2025-2026): DeepSeek V3.2 → <strong>R2</strong> (2026 初)、Qwen3-Max → <strong>Qwen3.5</strong> (2026-02)、Kimi K2.5、GLM-Z1 等, 把 RL + verifier + 过程奖励走通并保持开源权重.</li></ul><p>→ <strong>统计学含义</strong>: 不再只是 next-token 似然, 而是 MCTS + PRM + verifiable reward 上的策略优化; 模型从&quot;模仿分布&quot; 变 &quot;在状态空间搜解&quot;. 这把强化学习 (RL) 从边缘推成 LLM 训练 core 环, 且 2026 年推理算力曲线比预训练更陡 —— &quot;推理时算力&quot; 成为新的军备竞赛主轴.</p><h3 id="_8-5-2-百万-token-上下文与-kv-attention-革新" tabindex="-1">8.5.2 百万 token 上下文与 KV / attention 革新 <a class="header-anchor" href="#_8-5-2-百万-token-上下文与-kv-attention-革新" aria-label="Permalink to &quot;8.5.2 百万 token 上下文与 KV / attention 革新&quot;">​</a></h3><ul><li>2024 Gemini 1.5 Pro 首秀 1M context; 2026-03 <strong>Claude Opus 4.6 / Sonnet 4.6 把 1M context 转正为 GA</strong> (标准价、无溢价), Gemini 3 / Claude 5 延续 1M+ 原生支持, OpenAI 400K 走&quot;短上下文快推理&quot; 路线.</li><li>技术栈: sparse attention + sink token + RoPE 外插改进 (YaRN / LongRoPE) + KV 量化 (FP8 / INT4) + PagedAttention.</li><li>→ 把 <a href="./../ai-ml/transformer">第十二部分 §2 MHA</a> 与 <a href="./../ai-ml/backprop">§3 backprop</a> 里 attention 显存 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><msup><mi>T</mi><mn>2</mn></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(T^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的容器打到工程极限; 长上下文从&quot;演示指标&quot; 变成&quot;默认产品参数&quot;.</li></ul><h3 id="_8-5-3-nvidia-blackwell-与-hbm4-rubin" tabindex="-1">8.5.3 NVIDIA Blackwell 与 HBM4 / Rubin <a class="header-anchor" href="#_8-5-3-nvidia-blackwell-与-hbm4-rubin" aria-label="Permalink to &quot;8.5.3 NVIDIA Blackwell 与 HBM4 / Rubin&quot;">​</a></h3><ul><li><strong>B200</strong> (2024 发布 / 2025 量产): 双 die, 192 GB HBM3e, 8 PFLOPS FP4. 注意 B200 不再单芯片, 而是 2 个 reticle 用 NV-HBI 互连封装.</li><li><strong>GB200 NVL72</strong>: 36 块 Grace CPU + 72 块 B200 通过 1.8 TB/s NVLink 互联构建单机柜巨型张量机.</li><li><strong>HBM4</strong> (JEDEC 2025-04 定标; SK 海力士 2025-10 量产 → Samsung 2026-02 → Micron 2026-06 通过 NVIDIA 认证): 位宽 1024→2048 bit, <strong>单 stack 约 2 TB/s</strong>, 8-hi 24 GB / 12-hi 36 GB 起步; 配合 CXL 3.x 让 Tiered memory 走向主流.</li><li><strong>Rubin / Vera Rubin</strong> (CES 2026 发布, 2026 下半年量产): 72 Rubin GPU + 36 Vera CPU, NVLink 6 (每 GPU 3.6 TB/s) + ConnectX-9, 把&quot;整柜张量机&quot;再推上机架级 NVLink Domain; 2026 起 AI 硬件竞争从单卡打到整机柜.</li></ul><h3 id="_8-5-4-asic-与-xpu-谱系扩展" tabindex="-1">8.5.4 ASIC 与 XPU 谱系扩展 <a class="header-anchor" href="#_8-5-4-asic-与-xpu-谱系扩展" aria-label="Permalink to &quot;8.5.4 ASIC 与 XPU 谱系扩展&quot;">​</a></h3><ul><li><strong>Google TPU v6 Trillium</strong> / <strong>AMD Instinct MI450</strong> (2026, 432 GB HBM4, 19.6 TB/s, Helios 机架) / <strong>AWS Trainium 2</strong>: 都朝&quot;张量 + 互联&quot; 押大注; Intel <strong>Falcon Shores 2025-01 取消</strong> (仅作内部测试芯片), 转向机架级 <strong>Jaguar Shores</strong> —— 路线图再一次证明竞争重心在&quot;系统&quot; 而非&quot;单卡&quot;.</li><li><strong>Groq LPU</strong> 主打&quot;流式推理&quot;几十到几百 tok/s 单卡.</li><li><strong>Cerebras WSE-3</strong> 与 <strong>SambaNova SN40L</strong>: 整片晶圆级芯片 + 长上下文推理 SDK.</li><li><strong>Apple M5</strong> (2025-10) / <strong>M5 Pro/Max</strong> (2026-03) Neural Engine + <strong>骁龙 X Elite NPU</strong> 终端推理普及; 一台笔记本上跑百亿参数成产品级.</li><li><strong>国产</strong>: 昇腾 910C 大规模国产替代 → <strong>昇腾 950 超节点 Atlas 950 SuperPoD</strong> (2026 WAIC 首展: 1024 卡互联, 1 EFLOPS FP8 / 2 EFLOPS FP4, 256 TB 统一内存), 昇腾 384 超节点已商用 750+ 套; SMIC N+2 (7nm 等效) 2026 年底产能目标 7 万片/月; 寒武纪思元 590 / 阿里倚天 / 含光 亦成熟.</li></ul><h3 id="_8-5-5-agentic-ai-mcp-协议" tabindex="-1">8.5.5 Agentic AI + MCP 协议 <a class="header-anchor" href="#_8-5-5-agentic-ai-mcp-协议" aria-label="Permalink to &quot;8.5.5 Agentic AI + MCP 协议&quot;">​</a></h3><ul><li>2024 末 Anthropic 提出 <strong>MCP</strong> (Model Context Protocol) 让 LLM 与外部工具 / 数据源通过标准 JSON-RPC 协议交互.</li><li>2025-2026 GPT-5.x / Claude 5 / Gemini 3.x 把 tool use / 多轮调用 / sub-agents 工程化; <strong>Codex / claude-code 等 coding agent 成为首个&quot;产品级 agent&quot; 品类</strong>, &quot;Agent = LLM + tool loop + memory&quot; 成主流范式.</li><li>由此工具调用从单 API 进化为&quot;企业应用总线&quot;; 安全与沙箱 (Yamada / eBPF 隔离) 同步兴起, agent 从 demo 走向生产.</li></ul><h3 id="_8-5-6-量子计算-logical-qubit-时代" tabindex="-1">8.5.6 量子计算 &quot;logical qubit&quot; 时代 <a class="header-anchor" href="#_8-5-6-量子计算-logical-qubit-时代" aria-label="Permalink to &quot;8.5.6 量子计算 &quot;logical qubit&quot; 时代&quot;">​</a></h3><ul><li><strong>Google Willow</strong> (2024-12, 105 qubit): 首次演示表面码<strong>低于阈值 (below threshold)</strong> —— 错误率随码距增大指数下降, 纠错从理论变成工程曲线.</li><li><strong>Quantinuum Helios</strong> (2025-11): 98 物理 qubit 编码出 <strong>48 个逻辑 qubit</strong>, 2Q 门平均保真 99.92%, 是目前逻辑 qubit 的最高纪录.</li><li>2026 现实: 主流设备落在 <strong>10-48 逻辑 qubit</strong>, 尚未抵达 &quot;~100 logical&quot; 门槛; IBM 200 逻辑 qubit 的 Starling 预期 2028-2029.</li><li>但 <strong>Shor 还要 100 万-1 千万物理 qubit</strong> 才能威胁 RSA-2048; 业内&quot;Y2Q (years to quantum)&quot; 估计仍在 10-30 年.</li></ul><hr><h2 id="九、用一条数学线把-1936-2026-拉直" tabindex="-1">九、用一条数学线把 1936-2026 拉直 <a class="header-anchor" href="#九、用一条数学线把-1936-2026-拉直" aria-label="Permalink to &quot;九、用一条数学线把 1936-2026 拉直&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1936 TM        ──── &quot;可计算&quot; 形式化</span></span>
<span class="line"><span>                                        1948 Shannon 信息论 ── 熵 = 压缩下界 / 容量 = 通信上界</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>1980 协议理论 (Lamport / Pew / FLP) ─── 分布式算法理论起步</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>1995 RSA / DH / ZKP 一线 (Crypto)</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>2012 深度学习 = 反向传播 + GPU + 概率分布建模 大爆</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>2022 大模型工程化 = 自回归 + RLHF + 推理优化</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>2024 异构计算 = 数学调度优化 + 硬件窄并发抽象</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>2025 推理模型 + Agent = RL + verifier + 显式思维链;</span></span>
<span class="line"><span>       Blackwell B200 把&quot;芯片&quot;从单片推到多 reticle 系统</span></span>
<span class="line"><span>                                              │</span></span>
<span class="line"><span>2026 HBM4 (~2 TB/s) + CXL 3.2 + 昇腾 950 超节点 + 量子数十逻辑 qubit:</span></span>
<span class="line"><span>       数学调度不止 on-die, 跨 memory / chiplet / quantum 同步推上日程</span></span></code></pre></div><p><strong>这条线告诉读者</strong>: 数学在第零部分不是孤立基础, 而是<strong>在 1936-2026 这 90 年里每隔十几年就被换一次主角</strong>, 从离散的 TM → 概率的信息论 → 协议的不变式 → 数论的密码学 → 优化的 AI.</p><hr><h2 id="十、一句话点破每一年质变" tabindex="-1">十、一句话点破每一年质变 <a class="header-anchor" href="#十、一句话点破每一年质变" aria-label="Permalink to &quot;十、一句话点破每一年质变&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>事件</th><th>质变一句话</th></tr></thead><tbody><tr><td>1936</td><td>Turing</td><td>把&quot;算法&quot;从直觉推到形式</td></tr><tr><td>1945</td><td>von Neumann</td><td>把&quot;程序&quot;放进内存 → 抽象层从此可分</td></tr><tr><td>1947</td><td>晶体管</td><td>把&quot;开关&quot;从机电推到固态</td></tr><tr><td>1964</td><td>IBM S/360</td><td>把&quot;型号&quot;从一次性推到 ISA 兼容</td></tr><tr><td>1969</td><td>Unix</td><td>把&quot;OS&quot;从机房专属推到可移植代码</td></tr><tr><td>1969</td><td>ARPANET</td><td>把&quot;通信&quot;从点对点推到分组交换</td></tr><tr><td>1971</td><td>4004</td><td>把&quot;CPU&quot;从箱柜推到芯片</td></tr><tr><td>1981</td><td>IBM PC</td><td>把&quot;计算机&quot;从机房推到桌面</td></tr><tr><td>1991</td><td>Linux + WWW</td><td>把&quot;操作系统&quot;和&quot;信息消费&quot;各自开源 / 全球化</td></tr><tr><td>2006</td><td>AWS EC2</td><td>把&quot;服务器&quot;从资本推到按分钟计费</td></tr><tr><td>2007</td><td>iPhone</td><td>把&quot;计算机&quot;从桌面推到口袋 (ARM 击穿)</td></tr><tr><td>2012</td><td>AlexNet + CUDA</td><td>把&quot;GPU&quot;从图形推到通用张量</td></tr><tr><td>2017</td><td>Transformer</td><td>把&quot;序列建模&quot;从时间串联推到并行 attention</td></tr><tr><td>2022</td><td>ChatGPT</td><td>把&quot;AI&quot;从论文推到日常工具</td></tr><tr><td>2024</td><td>XPU 异构</td><td>把&quot;CPU 一统天下&quot;推到分工表</td></tr><tr><td>2025</td><td>推理模型 / DeepSeek 时刻</td><td>把&quot;LLM&quot;从续写推到 RL 增强推理; 开源踩穿定价</td></tr><tr><td>2025</td><td>Blackwell B200 / GB200</td><td>把&quot;GPU&quot;从单片推到 multi-reticle + 整柜张量机</td></tr><tr><td>2025</td><td>MCP / Agentic AI</td><td>把&quot;LLM&quot;从问答推到工具总线 + 多轮 Agent</td></tr><tr><td>2026</td><td>HBM4 三家量产 + Rubin / MI450 + 昇腾 950</td><td>把&quot;算力&quot;从单供应商单片推到整柜多源分工</td></tr><tr><td>2026</td><td>量子 10-48 逻辑 qubit</td><td>把纠错从物理实验推到工程爬坡</td></tr></tbody></table><hr><h2 id="十一、结束-速查表" tabindex="-1">十一、结束 + 速查表 <a class="header-anchor" href="#十一、结束-速查表" aria-label="Permalink to &quot;十一、结束 + 速查表&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>一页快速唤回:</p><ul><li><strong>1936 Turing</strong>: 算法形式化; 不可判定性.</li><li><strong>1945 von Neumann</strong>: 存储程序 ISA; CPU + 内存 + IO 三分.</li><li><strong>1947 晶体管 + 1958 IC</strong>: 让大规模逻辑可堆.</li><li><strong>1964 IBM 360</strong>: 引入 ISA 抽象; &quot;兼容&quot;成为商品属性.</li><li><strong>1969 Unix + ARPANET</strong>: OS 可移植 + 分组交换.</li><li><strong>1971 Intel 4004</strong>: CPU-on-chip; 微处理器时代.</li><li><strong>1981 IBM PC</strong>: x86 + DOS, Wintel 出芽.</li><li><strong>1991 Linux + WWW</strong>: 开源 OS + 全球网.</li><li><strong>1995 商业 web</strong>: 浏览器, LAMP stack.</li><li><strong>2006 AWS</strong>: 云原生起.</li><li><strong>2007 iPhone</strong>: ARM 移动逆袭.</li><li><strong>2012 AlexNet + CUDA</strong>: GPU = 张量计算事实标准.</li><li><strong>2017 Transformer</strong>: 并行 attention 取代 RNN.</li><li><strong>2022 ChatGPT</strong>: 大模型工程化, 用户数年破亿.</li><li><strong>2024 XPU</strong>: CPU + GPU + DPU + NPU + 量子预研.</li><li><strong>2025 Reasoning + Blackwell</strong>: 推理模型把 RL 推上 LLM 主舞台; B200 / GB200 把 GPU 推到整柜张量机.</li><li><strong>2025 DeepSeek 时刻</strong>: 开源踩穿闭源定价; 中国开源路线齐发.</li><li><strong>2025 MCP / Agentic</strong>: LLM 进化为 Agent + tool bus.</li><li><strong>2026 HBM4 (2 TB/s) + Rubin / MI450 + 昇腾 950 + 量子数十逻辑 qubit</strong>: 整柜算力 + 多源供应链; 逻辑 qubit 纠错进入工程爬坡.</li></ul></div><hr><p>下一篇: <a href="./abstraction-layers">2. 抽象层级: 从晶体管到 AI 模型的十层金字塔</a>.</p>`,119)])])}const g=a(o,[["render",i]]);export{c as __pageData,g as default};
